/**
 ******************************************************************************
 * @file    test_battery_monitor.c
 * TEAM CODE (owner: Brendon - battery monitor and USB-C MSC) - written by the BJT2 team, not generated by STM32CubeMX.
 * @brief   Unit tests for the 1 Hz battery snapshot service.
 *
 * Owner: Brendon Bone (PD5b).
 *
 * Coverage: gauge-absent behaviour (monitor stays inert, alarms never trip),
 * the exact 1 Hz poll cadence including tick wrap-around, partial-read
 * invalidation and recovery, the 30% / 10% alarm assert boundaries (PD2 reqs
 * 2.19/2.20) plus the 32% / 12% hysteresis release thresholds (dead-band
 * hold, anti-chatter sequences, latch survival across invalid polls), the
 * speaker lockout latch (sets below 10%, holds to 31%, releases at 32%,
 * re-arms, never moved by an invalid poll, reported even while invalid),
 * the time-to-empty / time-to-full reads (only after five good core reads, a
 * failed time read = 65535 without invalidating the snapshot, an invalid
 * snapshot = 65535), the instant current read (Current() right after the
 * five core reads and before the time reads, a failed read falls back to
 * AverageCurrent, is flagged (current_now_ok 0) and keeps the snapshot
 * valid, 0 in an invalid snapshot),
 * the debug SOC override (only the SOC is replaced, it
 * drives the low/critical alarms and the lockout, set/clear/expiry poll at
 * once, expiry wrap-safe in BatMon_Tick, the latches go on from the injected
 * SOC when it ends, the plausibility check sees the injected SOC, never
 * hides a gauge failure, refused without a gauge or above 100%),
 * plausibility rejection of corrupt reads, and NULL-safety of every accessor.
 ******************************************************************************
 */
#include "unity.h"
#include "battery_monitor.h"
#include "bq34z100.h"
#include "mock_bq_bus.h"

#include <string.h>

static Battery_Monitor s_mon;

void setUp(void)
{
    MockBus_Reset();
    memset(&s_mon, 0, sizeof(s_mon));
}

void tearDown(void)
{
}

#define ASSERT_BUS_CLEAN()                                            \
    do {                                                              \
        TEST_ASSERT_EQUAL_UINT32(0U, MockBus_Mismatches());           \
        TEST_ASSERT_EQUAL_UINT32(0U, MockBus_Unconsumed());           \
        TEST_ASSERT_EQUAL_UINT32(0U, MockBus_Unexpected());           \
    } while (0)

/* Queue the five core reads of one poll, in the order batmon_poll issues
 * them: Voltage, AverageCurrent, SOC, RemainingCapacity, FullChargeCapacity. */
static void queue_core_reads(uint16_t v_mV, int16_t i_mA, uint8_t soc,
                             uint16_t rem, uint16_t fcc,
                             int fail_v, int fail_i, int fail_soc,
                             int fail_rem, int fail_fcc)
{
    const uint8_t v_b[2]   = {(uint8_t)(v_mV & 0xFFU), (uint8_t)(v_mV >> 8)};
    const uint16_t i_u     = (uint16_t)i_mA;
    const uint8_t i_b[2]   = {(uint8_t)(i_u & 0xFFU), (uint8_t)(i_u >> 8)};
    const uint8_t soc_b[1] = {soc};
    const uint8_t rem_b[2] = {(uint8_t)(rem & 0xFFU), (uint8_t)(rem >> 8)};
    const uint8_t fcc_b[2] = {(uint8_t)(fcc & 0xFFU), (uint8_t)(fcc >> 8)};

    MockBus_ExpectRead(BQ34Z100_CMD_VOLTAGE, v_b, 2U, fail_v ? -1 : 0);
    MockBus_ExpectRead(BQ34Z100_CMD_AVERAGE_CURRENT, i_b, 2U, fail_i ? -1 : 0);
    MockBus_ExpectRead(BQ34Z100_CMD_STATE_OF_CHARGE, soc_b, 1U, fail_soc ? -1 : 0);
    MockBus_ExpectRead(BQ34Z100_CMD_REMAINING_CAPACITY, rem_b, 2U, fail_rem ? -1 : 0);
    MockBus_ExpectRead(BQ34Z100_CMD_FULL_CHARGE_CAPACITY, fcc_b, 2U, fail_fcc ? -1 : 0);
}

/* Queue the three extra reads batmon_poll adds after five successful core
 * reads, in its order: Current() (the instant current, signed mA), then
 * AverageTimeToEmpty and AverageTimeToFull (minutes). Every test queues the
 * extras through here, so the read sequence is written down once. */
static void queue_extra_reads(int16_t now_mA, uint16_t tte_min, uint16_t ttf_min,
                              int fail_now, int fail_tte, int fail_ttf)
{
    const uint16_t now_u   = (uint16_t)now_mA;
    const uint8_t now_b[2] = {(uint8_t)(now_u & 0xFFU), (uint8_t)(now_u >> 8)};
    const uint8_t tte_b[2] = {(uint8_t)(tte_min & 0xFFU), (uint8_t)(tte_min >> 8)};
    const uint8_t ttf_b[2] = {(uint8_t)(ttf_min & 0xFFU), (uint8_t)(ttf_min >> 8)};

    MockBus_ExpectRead(BQ34Z100_CMD_CURRENT, now_b, 2U, fail_now ? -1 : 0);
    MockBus_ExpectRead(BQ34Z100_CMD_AVG_TIME_TO_EMPTY, tte_b, 2U, fail_tte ? -1 : 0);
    MockBus_ExpectRead(BQ34Z100_CMD_AVG_TIME_TO_FULL, ttf_b, 2U, fail_ttf ? -1 : 0);
}

/* Queue every read of one poll. The three extras only follow when all five
 * core reads succeed (a poll with a failed core read must not issue them:
 * the mock counts them as unexpected); here the instant current equals the
 * average and the times return the gauge's "no estimate", 65535. */
static void queue_poll(uint16_t v_mV, int16_t i_mA, uint8_t soc,
                       uint16_t rem, uint16_t fcc,
                       int fail_v, int fail_i, int fail_soc,
                       int fail_rem, int fail_fcc)
{
    queue_core_reads(v_mV, i_mA, soc, rem, fcc,
                     fail_v, fail_i, fail_soc, fail_rem, fail_fcc);
    if (!fail_v && !fail_i && !fail_soc && !fail_rem && !fail_fcc) {
        queue_extra_reads(i_mA, BATMON_TIME_UNKNOWN, BATMON_TIME_UNKNOWN, 0, 0, 0);
    }
}

static void queue_good_poll(uint16_t v_mV, int16_t i_mA, uint8_t soc,
                            uint16_t rem, uint16_t fcc)
{
    queue_poll(v_mV, i_mA, soc, rem, fcc, 0, 0, 0, 0, 0);
}

/* Init with a present gauge and one good snapshot (3300 mV, -150 mA, soc%). */
static void init_with_soc(uint8_t soc)
{
    const int ready[] = {0};

    MockBus_QueueReady(ready, 1U);
    queue_good_poll(3300U, -150, soc, 1700U, 3400U);
    TEST_ASSERT_EQUAL(BATMON_OK, BatMon_Init(&s_mon, MockBus_Iface()));
}

/* -------------------------------------------------------------------------- */
/* Initialisation                                                              */
/* -------------------------------------------------------------------------- */

static void test_init_rejects_bad_params(void)
{
    BQ_Bus bad;

    TEST_ASSERT_EQUAL(BATMON_BAD_PARAM, BatMon_Init(NULL, MockBus_Iface()));
    TEST_ASSERT_EQUAL(BATMON_BAD_PARAM, BatMon_Init(&s_mon, NULL));

    memset(&bad, 0, sizeof(bad));   /* missing mem_read / is_ready */
    TEST_ASSERT_EQUAL(BATMON_BAD_PARAM, BatMon_Init(&s_mon, &bad));
}

static void test_init_absent_gauge_stays_inert(void)
{
    const int ready[] = {-1, -1, -1};
    Battery_Snapshot_t snap;

    MockBus_QueueReady(ready, 3U);
    TEST_ASSERT_EQUAL(BATMON_NO_GAUGE, BatMon_Init(&s_mon, MockBus_Iface()));
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_GaugePresent(&s_mon));

    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(0U, snap.valid);
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsLowBattery(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsCriticalBattery(&s_mon));

    /* No poll traffic may have happened. */
    TEST_ASSERT_EQUAL_UINT32(0U, MockBus_Unexpected());
}

static void test_init_present_takes_immediate_snapshot(void)
{
    Battery_Snapshot_t snap;

    init_with_soc(80U);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_GaugePresent(&s_mon));

    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(1U, snap.valid);
    TEST_ASSERT_EQUAL_UINT16(3300U, snap.voltage_mV);
    TEST_ASSERT_EQUAL_INT16(-150, snap.current_mA);
    TEST_ASSERT_EQUAL_INT16(-150, snap.current_now_mA);
    TEST_ASSERT_EQUAL_UINT8(80U, snap.soc_pct);
    TEST_ASSERT_EQUAL_UINT16(1700U, snap.remaining_mAh);
    TEST_ASSERT_EQUAL_UINT16(3400U, snap.full_capacity_mAh);
    ASSERT_BUS_CLEAN();
}

/* -------------------------------------------------------------------------- */
/* Poll cadence                                                                */
/* -------------------------------------------------------------------------- */

static void test_tick_does_not_poll_before_interval(void)
{
    init_with_soc(80U);

    /* 999 ms after the init-time poll reference: nothing may happen. */
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_Tick(&s_mon, 999U));
    ASSERT_BUS_CLEAN();
}

static void test_tick_polls_at_exactly_one_second(void)
{
    init_with_soc(80U);

    queue_good_poll(3290U, -140, 79U, 1690U, 3400U);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_Tick(&s_mon, 1000U));

    /* 500 ms later: too soon again. */
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_Tick(&s_mon, 1500U));

    queue_good_poll(3280U, -140, 79U, 1680U, 3400U);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_Tick(&s_mon, 2000U));
    ASSERT_BUS_CLEAN();
}

static void test_tick_survives_tick_wraparound(void)
{
    init_with_soc(80U);

    /* Jump near the 32-bit tick wrap. */
    queue_good_poll(3300U, -150, 80U, 1700U, 3400U);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_Tick(&s_mon, 0xFFFFFC00U));

    /* +512 ms (still pre-wrap): too soon. */
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_Tick(&s_mon, 0xFFFFFE00U));

    /* Now the tick wraps; unsigned elapsed = 0x200 - 0xFFFFFC00 = 1536 ms. */
    queue_good_poll(3300U, -150, 80U, 1700U, 3400U);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_Tick(&s_mon, 0x00000200U));
    ASSERT_BUS_CLEAN();
}

static void test_tick_ignores_absent_gauge_and_null(void)
{
    const int ready[] = {-1, -1, -1};

    MockBus_QueueReady(ready, 3U);
    (void)BatMon_Init(&s_mon, MockBus_Iface());

    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_Tick(&s_mon, 5000U));
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_Tick(NULL, 5000U));
    TEST_ASSERT_EQUAL_UINT32(0U, MockBus_Unexpected());
}

/* -------------------------------------------------------------------------- */
/* Failure handling and recovery                                               */
/* -------------------------------------------------------------------------- */

static void test_partial_read_failure_invalidates_snapshot(void)
{
    Battery_Snapshot_t snap;

    init_with_soc(20U);   /* valid, and low (20 < 30) */
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsLowBattery(&s_mon));

    /* SOC read NACKs mid-poll; the remaining reads still happen (port of the
     * demo's s |= pattern) but the snapshot must come out invalid. */
    queue_poll(3300U, -150, 20U, 1700U, 3400U, 0, 0, 1, 0, 0);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_Tick(&s_mon, 1000U));

    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(0U, snap.valid);
    /* Alarms must not fire on stale data. */
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsLowBattery(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsCriticalBattery(&s_mon));
    ASSERT_BUS_CLEAN();
}

static void test_snapshot_recovers_on_next_good_poll(void)
{
    Battery_Snapshot_t snap;

    init_with_soc(80U);

    queue_poll(3300U, -150, 80U, 1700U, 3400U, 1, 0, 0, 0, 0);
    (void)BatMon_Tick(&s_mon, 1000U);
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(0U, snap.valid);

    queue_good_poll(3295U, -150, 25U, 850U, 3400U);
    (void)BatMon_Tick(&s_mon, 2000U);
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(1U, snap.valid);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsLowBattery(&s_mon));
    ASSERT_BUS_CLEAN();
}

/* -------------------------------------------------------------------------- */
/* Alarm thresholds (PD2 reqs 2.19 / 2.20)                                     */
/* -------------------------------------------------------------------------- */

static void poll_soc(uint8_t soc, uint32_t at_ms)
{
    queue_good_poll(3300U, -150, soc, 1000U, 3400U);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_Tick(&s_mon, at_ms));
}

static void test_low_battery_boundary_at_30_percent(void)
{
    init_with_soc(80U);

    poll_soc(31U, 1000U);
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsLowBattery(&s_mon));

    poll_soc(30U, 2000U);   /* threshold is strictly below 30 */
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsLowBattery(&s_mon));

    poll_soc(29U, 3000U);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsLowBattery(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsCriticalBattery(&s_mon));
    ASSERT_BUS_CLEAN();
}

static void test_critical_battery_boundary_at_10_percent(void)
{
    init_with_soc(80U);

    poll_soc(11U, 1000U);
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsCriticalBattery(&s_mon));

    poll_soc(10U, 2000U);
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsCriticalBattery(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsLowBattery(&s_mon));

    poll_soc(9U, 3000U);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsCriticalBattery(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsLowBattery(&s_mon));
    ASSERT_BUS_CLEAN();
}

/* -------------------------------------------------------------------------- */
/* Alarm hysteresis (Schmitt-trigger latching: assert <30/<10, clear >=32/>=12) */
/* -------------------------------------------------------------------------- */

static void test_low_alarm_releases_with_hysteresis_on_rising_soc(void)
{
    init_with_soc(80U);

    poll_soc(29U, 1000U);   /* below 30: assert */
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsLowBattery(&s_mon));

    poll_soc(30U, 2000U);   /* dead band: hold */
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsLowBattery(&s_mon));

    poll_soc(31U, 3000U);   /* dead band: hold */
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsLowBattery(&s_mon));

    poll_soc(32U, 4000U);   /* at the clear threshold: release */
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsLowBattery(&s_mon));
    ASSERT_BUS_CLEAN();
}

static void test_critical_alarm_releases_with_hysteresis_on_rising_soc(void)
{
    init_with_soc(80U);

    poll_soc(9U, 1000U);    /* below 10: assert */
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsCriticalBattery(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsLowBattery(&s_mon));

    poll_soc(10U, 2000U);   /* dead band: hold */
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsCriticalBattery(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsLowBattery(&s_mon));

    poll_soc(11U, 3000U);   /* dead band: hold */
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsCriticalBattery(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsLowBattery(&s_mon));

    poll_soc(12U, 4000U);   /* at the clear threshold: critical releases... */
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsCriticalBattery(&s_mon));
    /* ...but low stays latched (12% is far below its 32% clear level). */
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsLowBattery(&s_mon));
    ASSERT_BUS_CLEAN();
}

static void test_low_alarm_holds_through_dead_band_chatter(void)
{
    /* SOC noise-hovering around the 30% threshold: without hysteresis this
     * sequence would toggle the alarm three times; with it the alarm asserts
     * once and holds through the entire sequence. */
    static const uint8_t seq[] = {29U, 30U, 29U, 31U, 30U};
    uint32_t at_ms = 1000U;
    size_t   k;

    init_with_soc(80U);

    for (k = 0U; k < sizeof(seq) / sizeof(seq[0]); k++) {
        poll_soc(seq[k], at_ms);
        TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsLowBattery(&s_mon));
        at_ms += 1000U;
    }
    ASSERT_BUS_CLEAN();
}

static void test_alarm_latch_survives_invalid_poll(void)
{
    init_with_soc(80U);

    poll_soc(29U, 1000U);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsLowBattery(&s_mon));

    /* SOC read NACKs: the snapshot goes invalid, so the predicate gates to 0
     * (alarms never report on stale data), but the internal latch must be
     * held rather than cleared. */
    queue_poll(3300U, -150, 29U, 1000U, 3400U, 0, 0, 1, 0, 0);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_Tick(&s_mon, 2000U));
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsLowBattery(&s_mon));

    /* Next valid poll lands in the dead band: the held latch reports again. */
    poll_soc(31U, 3000U);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsLowBattery(&s_mon));
    ASSERT_BUS_CLEAN();
}

static void test_first_poll_in_dead_band_does_not_assert(void)
{
    /* First-ever reading inside the 30-31% dead band: the latch starts
     * cleared and must not assert without actually crossing below 30%. */
    init_with_soc(31U);
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsLowBattery(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsCriticalBattery(&s_mon));
    ASSERT_BUS_CLEAN();
}

/* -------------------------------------------------------------------------- */
/* Speaker lockout latch (PD2 req 2.20: sets < 10%, releases >= 32%)          */
/* -------------------------------------------------------------------------- */

static void test_lockout_sets_with_critical_below_10_percent(void)
{
    init_with_soc(80U);
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsSpeakerLockout(&s_mon));

    poll_soc(10U, 1000U);   /* strictly below 10, like the critical alarm */
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsSpeakerLockout(&s_mon));

    poll_soc(9U, 2000U);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsSpeakerLockout(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsCriticalBattery(&s_mon));
    ASSERT_BUS_CLEAN();
}

static void test_lockout_holds_until_32_percent(void)
{
    init_with_soc(80U);

    poll_soc(9U, 1000U);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsSpeakerLockout(&s_mon));

    poll_soc(15U, 2000U);   /* the critical alarm has released (>= 12%)... */
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsCriticalBattery(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsSpeakerLockout(&s_mon));   /* ...the lockout has not */

    poll_soc(25U, 3000U);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsSpeakerLockout(&s_mon));

    poll_soc(31U, 4000U);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsSpeakerLockout(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsLowBattery(&s_mon));

    poll_soc(32U, 5000U);   /* releases at the same reading as the low alarm */
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsSpeakerLockout(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsLowBattery(&s_mon));
    ASSERT_BUS_CLEAN();
}

static void test_lockout_rearms_on_next_drop_below_10_percent(void)
{
    init_with_soc(80U);

    poll_soc(9U, 1000U);
    poll_soc(32U, 2000U);
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsSpeakerLockout(&s_mon));

    /* Discharging again: the low band and the 10-11% critical dead band do
     * not lock the speaker; the next reading below 10% does. */
    poll_soc(20U, 3000U);
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsSpeakerLockout(&s_mon));
    poll_soc(11U, 4000U);
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsSpeakerLockout(&s_mon));
    poll_soc(10U, 5000U);
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsSpeakerLockout(&s_mon));
    poll_soc(9U, 6000U);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsSpeakerLockout(&s_mon));
    ASSERT_BUS_CLEAN();
}

static void test_lockout_held_and_reported_through_invalid_polls(void)
{
    Battery_Snapshot_t snap;

    init_with_soc(80U);
    poll_soc(9U, 1000U);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsSpeakerLockout(&s_mon));

    /* Voltage read NACKs while the SOC bytes say 80%: used, this poll would
     * release the lockout. It is invalid, so the latch holds, and unlike the
     * critical alarm the predicate keeps reporting it (no unmute on a gauge
     * read failure). */
    queue_poll(3300U, -150, 80U, 1700U, 3400U, 1, 0, 0, 0, 0);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_Tick(&s_mon, 2000U));
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(0U, snap.valid);
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsCriticalBattery(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsSpeakerLockout(&s_mon));

    /* Every read succeeds but the SOC is impossible (> 100%, so also >= 32%). */
    poll_soc(101U, 3000U);
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(0U, snap.valid);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsSpeakerLockout(&s_mon));

    /* The next valid reading decides again: 31% still holds. */
    poll_soc(31U, 4000U);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsSpeakerLockout(&s_mon));
    ASSERT_BUS_CLEAN();
}

static void test_lockout_not_set_by_invalid_polls(void)
{
    init_with_soc(80U);

    /* SOC read NACKs: invalid, whatever the bytes say. */
    queue_poll(3300U, -150, 5U, 100U, 3400U, 0, 0, 1, 0, 0);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_Tick(&s_mon, 1000U));
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsSpeakerLockout(&s_mon));

    /* Every read succeeds and says 5%, but the voltage is outside the window. */
    queue_good_poll(1999U, -150, 5U, 100U, 3400U);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_Tick(&s_mon, 2000U));
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsSpeakerLockout(&s_mon));

    /* Impossible SOC (> 100%). */
    poll_soc(101U, 3000U);
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsSpeakerLockout(&s_mon));
    ASSERT_BUS_CLEAN();
}

static void test_lockout_latched_by_first_reading_at_init(void)
{
    /* Boot with an already-critical battery: the init-time poll latches the
     * lockout, so BrendonTask's first publish reports it straight away. */
    init_with_soc(8U);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsSpeakerLockout(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsCriticalBattery(&s_mon));
    ASSERT_BUS_CLEAN();
}

static void test_lockout_cleared_by_init_and_absent_without_gauge(void)
{
    const int ready[] = {-1, -1, -1};

    s_mon.lockout_latched = 1U;   /* left over from an earlier run: Init must clear it */
    MockBus_QueueReady(ready, 3U);
    TEST_ASSERT_EQUAL(BATMON_NO_GAUGE, BatMon_Init(&s_mon, MockBus_Iface()));
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsSpeakerLockout(&s_mon));

    /* No gauge, no polls, no lockout: the speaker is never muted for nothing. */
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_Tick(&s_mon, 5000U));
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsSpeakerLockout(&s_mon));
    TEST_ASSERT_EQUAL_UINT32(0U, MockBus_Unexpected());
}

/* -------------------------------------------------------------------------- */
/* Time to empty / to full (PD2 B9: shown on the Battery screen)              */
/* -------------------------------------------------------------------------- */

/* One poll whose five core reads succeed (3300 mV, i_mA, soc) followed by
 * the instant current (= i_mA) and the two time reads with the given values
 * or failures. */
static void poll_times(int16_t i_mA, uint8_t soc,
                       uint16_t tte_min, uint16_t ttf_min,
                       int fail_tte, int fail_ttf, uint32_t at_ms)
{
    queue_core_reads(3300U, i_mA, soc, 1700U, 3400U, 0, 0, 0, 0, 0);
    queue_extra_reads(i_mA, tte_min, ttf_min, 0, fail_tte, fail_ttf);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_Tick(&s_mon, at_ms));
}

static void test_times_unknown_after_init(void)
{
    const int ready[] = {-1, -1, -1};
    Battery_Snapshot_t snap;

    /* setUp zeroed the monitor, so 65535 here comes from BatMon_Init. */
    MockBus_QueueReady(ready, 3U);
    TEST_ASSERT_EQUAL(BATMON_NO_GAUGE, BatMon_Init(&s_mon, MockBus_Iface()));
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT16(BATMON_TIME_UNKNOWN, snap.tte_min);
    TEST_ASSERT_EQUAL_UINT16(BATMON_TIME_UNKNOWN, snap.ttf_min);
    TEST_ASSERT_EQUAL_UINT32(0U, MockBus_Unexpected());
}

static void test_times_land_in_snapshot(void)
{
    Battery_Snapshot_t snap;

    init_with_soc(80U);   /* its time reads return 65535 */
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT16(BATMON_TIME_UNKNOWN, snap.tte_min);
    TEST_ASSERT_EQUAL_UINT16(BATMON_TIME_UNKNOWN, snap.ttf_min);

    /* Discharging: the gauge estimates the time to empty only. */
    poll_times(-150, 79U, 75U, BATMON_TIME_UNKNOWN, 0, 0, 1000U);
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(1U, snap.valid);
    TEST_ASSERT_EQUAL_UINT16(75U, snap.tte_min);
    TEST_ASSERT_EQUAL_UINT16(BATMON_TIME_UNKNOWN, snap.ttf_min);

    /* Charging: the time to full only. */
    poll_times(850, 80U, BATMON_TIME_UNKNOWN, 42U, 0, 0, 2000U);
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(1U, snap.valid);
    TEST_ASSERT_EQUAL_UINT16(BATMON_TIME_UNKNOWN, snap.tte_min);
    TEST_ASSERT_EQUAL_UINT16(42U, snap.ttf_min);
    ASSERT_BUS_CLEAN();
}

static void test_tte_read_failure_gives_unknown_and_stays_valid(void)
{
    Battery_Snapshot_t snap;

    init_with_soc(80U);
    poll_times(-150, 80U, 75U, BATMON_TIME_UNKNOWN, 0, 0, 1000U);

    /* TTE NACKs: no estimate (not the old 75), but the reading itself is
     * still good: valid, new SOC used by the alarms. */
    poll_times(-150, 25U, 74U, BATMON_TIME_UNKNOWN, 1, 0, 2000U);
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(1U, snap.valid);
    TEST_ASSERT_EQUAL_UINT8(25U, snap.soc_pct);
    TEST_ASSERT_EQUAL_UINT16(BATMON_TIME_UNKNOWN, snap.tte_min);
    TEST_ASSERT_EQUAL_UINT16(BATMON_TIME_UNKNOWN, snap.ttf_min);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsLowBattery(&s_mon));
    ASSERT_BUS_CLEAN();
}

static void test_ttf_read_failure_gives_unknown_and_stays_valid(void)
{
    Battery_Snapshot_t snap;

    init_with_soc(50U);
    poll_times(850, 50U, BATMON_TIME_UNKNOWN, 42U, 0, 0, 1000U);

    /* TTF NACKs: no estimate (not the old 42); everything else stands. */
    poll_times(850, 51U, BATMON_TIME_UNKNOWN, 41U, 0, 1, 2000U);
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(1U, snap.valid);
    TEST_ASSERT_EQUAL_UINT8(51U, snap.soc_pct);
    TEST_ASSERT_EQUAL_INT16(850, snap.current_mA);
    TEST_ASSERT_EQUAL_UINT16(BATMON_TIME_UNKNOWN, snap.tte_min);
    TEST_ASSERT_EQUAL_UINT16(BATMON_TIME_UNKNOWN, snap.ttf_min);
    ASSERT_BUS_CLEAN();
}

static void test_core_failure_skips_time_reads(void)
{
    Battery_Snapshot_t snap;
    uint32_t at_ms = 2000U;
    int k;

    init_with_soc(80U);
    poll_times(-150, 80U, 75U, BATMON_TIME_UNKNOWN, 0, 0, 1000U);

    /* Each of the five core reads failing in turn: the poll is invalid, no
     * extra read follows (neither the instant current nor a time: each would
     * count as unexpected) and the old 75 min estimate is dropped. */
    for (k = 0; k < 5; k++) {
        queue_core_reads(3300U, -150, 80U, 1700U, 3400U,
                         k == 0, k == 1, k == 2, k == 3, k == 4);
        TEST_ASSERT_EQUAL_UINT8(1U, BatMon_Tick(&s_mon, at_ms));
        TEST_ASSERT_EQUAL_UINT32(0U, MockBus_Unexpected());
        BatMon_GetSnapshot(&s_mon, &snap);
        TEST_ASSERT_EQUAL_UINT8(0U, snap.valid);
        TEST_ASSERT_EQUAL_INT16(0, snap.current_now_mA);
        TEST_ASSERT_EQUAL_UINT16(BATMON_TIME_UNKNOWN, snap.tte_min);
        TEST_ASSERT_EQUAL_UINT16(BATMON_TIME_UNKNOWN, snap.ttf_min);
        at_ms += 1000U;
    }

    /* The gauge answers again: the estimate is back with the next poll. */
    poll_times(-150, 80U, 73U, BATMON_TIME_UNKNOWN, 0, 0, at_ms);
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(1U, snap.valid);
    TEST_ASSERT_EQUAL_UINT16(73U, snap.tte_min);
    ASSERT_BUS_CLEAN();
}

static void test_implausible_poll_reports_unknown_times(void)
{
    Battery_Snapshot_t snap;

    init_with_soc(80U);
    poll_times(-150, 80U, 75U, BATMON_TIME_UNKNOWN, 0, 0, 1000U);

    /* Every read succeeds, so the gauge is asked for the times, but the SOC
     * is impossible: the invalid snapshot carries no estimate. */
    poll_times(-150, 101U, 70U, BATMON_TIME_UNKNOWN, 0, 0, 2000U);
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(0U, snap.valid);
    TEST_ASSERT_EQUAL_UINT16(BATMON_TIME_UNKNOWN, snap.tte_min);
    TEST_ASSERT_EQUAL_UINT16(BATMON_TIME_UNKNOWN, snap.ttf_min);
    ASSERT_BUS_CLEAN();
}

/* -------------------------------------------------------------------------- */
/* Instant current (best-ui: battery_time.c's fast time to empty / to full)    */
/* -------------------------------------------------------------------------- */

static void test_instant_current_read_after_core_reads(void)
{
    Battery_Snapshot_t snap;

    init_with_soc(80U);

    /* Current() (0x10) comes right after the five core reads and before the
     * two time reads: the mock checks every register in order. The instant
     * value differs from AverageCurrent, so each lands in its own field. */
    queue_core_reads(3300U, -150, 80U, 1700U, 3400U, 0, 0, 0, 0, 0);
    queue_extra_reads(-420, 75U, BATMON_TIME_UNKNOWN, 0, 0, 0);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_Tick(&s_mon, 1000U));

    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(1U, snap.valid);
    TEST_ASSERT_EQUAL_INT16(-150, snap.current_mA);
    TEST_ASSERT_EQUAL_INT16(-420, snap.current_now_mA);
    TEST_ASSERT_EQUAL_UINT8(1U, snap.current_now_ok);   /* a real Current() reading */
    TEST_ASSERT_EQUAL_UINT16(75U, snap.tte_min);

    /* Charging: the sign is kept (two's complement on the bus). */
    queue_core_reads(3400U, 300, 81U, 1720U, 3400U, 0, 0, 0, 0, 0);
    queue_extra_reads(900, BATMON_TIME_UNKNOWN, 112U, 0, 0, 0);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_Tick(&s_mon, 2000U));
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_INT16(300, snap.current_mA);
    TEST_ASSERT_EQUAL_INT16(900, snap.current_now_mA);
    TEST_ASSERT_EQUAL_UINT8(1U, snap.current_now_ok);
    TEST_ASSERT_EQUAL_UINT16(112U, snap.ttf_min);
    ASSERT_BUS_CLEAN();
}

static void test_instant_current_failure_falls_back_to_average(void)
{
    Battery_Snapshot_t snap;

    init_with_soc(80U);

    /* Current() NACKs: AverageCurrent stands in, the snapshot stays valid,
     * the new SOC still drives the alarms and both time reads still follow.
     * current_now_ok 0 says the value is the stand-in, so battery_time.c
     * leaves it out of its average. */
    queue_core_reads(3300U, -150, 25U, 850U, 3400U, 0, 0, 0, 0, 0);
    queue_extra_reads(-420, 75U, BATMON_TIME_UNKNOWN, 1, 0, 0);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_Tick(&s_mon, 1000U));

    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(1U, snap.valid);
    TEST_ASSERT_EQUAL_UINT8(25U, snap.soc_pct);
    TEST_ASSERT_EQUAL_INT16(-150, snap.current_mA);
    TEST_ASSERT_EQUAL_INT16(-150, snap.current_now_mA);
    TEST_ASSERT_EQUAL_UINT8(0U, snap.current_now_ok);
    TEST_ASSERT_EQUAL_UINT16(75U, snap.tte_min);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsLowBattery(&s_mon));

    /* The next good read is the instant value again, flagged as such. */
    queue_core_reads(3300U, -150, 25U, 849U, 3400U, 0, 0, 0, 0, 0);
    queue_extra_reads(-430, 74U, BATMON_TIME_UNKNOWN, 0, 0, 0);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_Tick(&s_mon, 2000U));
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_INT16(-430, snap.current_now_mA);
    TEST_ASSERT_EQUAL_UINT8(1U, snap.current_now_ok);
    ASSERT_BUS_CLEAN();
}

static void test_instant_current_zero_without_valid_reading(void)
{
    const int absent[] = {-1, -1, -1};
    const int present[] = {0};
    Battery_Snapshot_t snap;

    /* No gauge at init: 0, not whatever the instance held. */
    s_mon.snap.current_now_mA = 123;
    s_mon.snap.current_now_ok = 1U;
    MockBus_QueueReady(absent, 3U);
    TEST_ASSERT_EQUAL(BATMON_NO_GAUGE, BatMon_Init(&s_mon, MockBus_Iface()));
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_INT16(0, snap.current_now_mA);
    TEST_ASSERT_EQUAL_UINT8(0U, snap.current_now_ok);

    /* Found by the retry: its first poll carries the instant value. */
    MockBus_QueueReady(present, 1U);
    queue_core_reads(3300U, -150, 80U, 1700U, 3400U, 0, 0, 0, 0, 0);
    queue_extra_reads(-420, BATMON_TIME_UNKNOWN, BATMON_TIME_UNKNOWN, 0, 0, 0);
    TEST_ASSERT_EQUAL(BATMON_OK, BatMon_RetryProbe(&s_mon));
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_INT16(-420, snap.current_now_mA);
    TEST_ASSERT_EQUAL_UINT8(1U, snap.current_now_ok);

    /* A failed core read: invalid, no instant read, no old value either. */
    queue_core_reads(3300U, -150, 80U, 1700U, 3400U, 0, 0, 1, 0, 0);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_Tick(&s_mon, 1000U));
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(0U, snap.valid);
    TEST_ASSERT_EQUAL_INT16(0, snap.current_now_mA);
    TEST_ASSERT_EQUAL_UINT8(0U, snap.current_now_ok);

    /* Every read succeeds (the instant one too) but the SOC is impossible:
     * still no instant current from an invalid snapshot. */
    queue_core_reads(3300U, -150, 101U, 1700U, 3400U, 0, 0, 0, 0, 0);
    queue_extra_reads(-420, BATMON_TIME_UNKNOWN, BATMON_TIME_UNKNOWN, 0, 0, 0);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_Tick(&s_mon, 2000U));
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(0U, snap.valid);
    TEST_ASSERT_EQUAL_INT16(0, snap.current_now_mA);
    TEST_ASSERT_EQUAL_UINT8(0U, snap.current_now_ok);
    ASSERT_BUS_CLEAN();
}

/* -------------------------------------------------------------------------- */
/* Debug SOC override (the debug screen's battery fault injection)            */
/* -------------------------------------------------------------------------- */

static void test_soc_override_replaces_soc_keeps_real_readings(void)
{
    Battery_Snapshot_t snap;

    init_with_soc(80U);
    TEST_ASSERT_EQUAL(BATMON_OK, BatMon_SetSocOverride(&s_mon, 25U, 300U, 100U));
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_SocOverrideActive(&s_mon));

    /* The gauge still answers every read with its real values (79 %). Only
     * the SOC is replaced; voltage, both currents and the times are the
     * gauge's. */
    queue_core_reads(3290U, -140, 79U, 1690U, 3400U, 0, 0, 0, 0, 0);
    queue_extra_reads(-160, 75U, BATMON_TIME_UNKNOWN, 0, 0, 0);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_Tick(&s_mon, 100U));

    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(1U, snap.valid);
    TEST_ASSERT_EQUAL_UINT8(25U, snap.soc_pct);
    TEST_ASSERT_EQUAL_UINT16(3290U, snap.voltage_mV);
    TEST_ASSERT_EQUAL_INT16(-140, snap.current_mA);
    TEST_ASSERT_EQUAL_INT16(-160, snap.current_now_mA);
    TEST_ASSERT_EQUAL_UINT16(1690U, snap.remaining_mAh);
    TEST_ASSERT_EQUAL_UINT16(75U, snap.tte_min);
    TEST_ASSERT_EQUAL_UINT16(BATMON_TIME_UNKNOWN, snap.ttf_min);
    ASSERT_BUS_CLEAN();
}

static void test_soc_override_drives_low_critical_and_lockout(void)
{
    Battery_Snapshot_t snap;

    init_with_soc(80U);   /* the real battery stays at 80 % throughout */

    /* "Battery LOW 25%": low alarm only. */
    TEST_ASSERT_EQUAL(BATMON_OK, BatMon_SetSocOverride(&s_mon, 25U, 300U, 1000U));
    poll_soc(80U, 1000U);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsLowBattery(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsCriticalBattery(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsSpeakerLockout(&s_mon));

    /* "Battery CRIT 8%": critical alarm and the speaker lockout, polled at
     * once although the last poll was only 100 ms ago. */
    TEST_ASSERT_EQUAL(BATMON_OK, BatMon_SetSocOverride(&s_mon, 8U, 300U, 1100U));
    poll_soc(80U, 1100U);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsLowBattery(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsCriticalBattery(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsSpeakerLockout(&s_mon));

    /* "Battery OK 60%": above every release point, so all three clear. */
    TEST_ASSERT_EQUAL(BATMON_OK, BatMon_SetSocOverride(&s_mon, 60U, 300U, 1200U));
    poll_soc(80U, 1200U);
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(60U, snap.soc_pct);
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsLowBattery(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsCriticalBattery(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsSpeakerLockout(&s_mon));
    ASSERT_BUS_CLEAN();
}

static void test_soc_override_set_and_clear_poll_at_once(void)
{
    init_with_soc(80U);   /* polled at 0 ms: the next regular poll is at 1000 ms */

    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_Tick(&s_mon, 500U));

    /* Set: the very next tick polls, then the 1 s cadence resumes from it. */
    TEST_ASSERT_EQUAL(BATMON_OK, BatMon_SetSocOverride(&s_mon, 25U, 300U, 500U));
    poll_soc(80U, 500U);
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_Tick(&s_mon, 600U));

    /* Clear: the same again. */
    TEST_ASSERT_EQUAL(BATMON_OK, BatMon_SetSocOverride(&s_mon, 0U, 0U, 700U));
    poll_soc(80U, 700U);
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_Tick(&s_mon, 800U));
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_Tick(&s_mon, 1699U));
    ASSERT_BUS_CLEAN();
}

static void test_soc_override_clear_with_zero_seconds(void)
{
    Battery_Snapshot_t snap;

    init_with_soc(80U);
    TEST_ASSERT_EQUAL(BATMON_OK, BatMon_SetSocOverride(&s_mon, 8U, 300U, 1000U));
    poll_soc(80U, 1000U);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsSpeakerLockout(&s_mon));

    /* "Clear overrides": 0 s. The SOC value is ignored, so a clear can never
     * be refused for a bad one. The next poll reports the real 80 %. */
    TEST_ASSERT_EQUAL(BATMON_OK, BatMon_SetSocOverride(&s_mon, 255U, 0U, 1200U));
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_SocOverrideActive(&s_mon));
    TEST_ASSERT_EQUAL_UINT16(0U, BatMon_SocOverrideSecondsLeft(&s_mon, 1200U));
    poll_soc(80U, 1200U);
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(80U, snap.soc_pct);
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsCriticalBattery(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsSpeakerLockout(&s_mon));
    ASSERT_BUS_CLEAN();
}

static void test_soc_override_expires_after_n_seconds(void)
{
    Battery_Snapshot_t snap;

    init_with_soc(80U);
    TEST_ASSERT_EQUAL(BATMON_OK, BatMon_SetSocOverride(&s_mon, 25U, 2U, 1500U));
    TEST_ASSERT_EQUAL_UINT16(2U, BatMon_SocOverrideSecondsLeft(&s_mon, 1500U));
    poll_soc(80U, 1500U);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsLowBattery(&s_mon));

    /* A regular poll inside the 2 s still uses the override. */
    poll_soc(80U, 2600U);
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(25U, snap.soc_pct);

    /* 1 ms before the end: no poll due, still active. */
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_Tick(&s_mon, 3499U));
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_SocOverrideActive(&s_mon));
    TEST_ASSERT_EQUAL_UINT16(1U, BatMon_SocOverrideSecondsLeft(&s_mon, 3499U));

    /* At the end it stops and polls at once (only 900 ms after the last
     * poll), so the real 80 % is back and the low alarm releases. */
    poll_soc(80U, 3500U);
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_SocOverrideActive(&s_mon));
    TEST_ASSERT_EQUAL_UINT16(0U, BatMon_SocOverrideSecondsLeft(&s_mon, 3500U));
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(80U, snap.soc_pct);
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsLowBattery(&s_mon));
    ASSERT_BUS_CLEAN();
}

static void test_soc_override_seconds_left_rounds_up_and_wraps(void)
{
    init_with_soc(80U);

    /* 300 s from 1000 ms: a fresh override reads 300, and the count only
     * reaches 0 when it actually ends. No tick is called: no bus traffic. */
    TEST_ASSERT_EQUAL(BATMON_OK, BatMon_SetSocOverride(&s_mon, 25U, 300U, 1000U));
    TEST_ASSERT_EQUAL_UINT16(300U, BatMon_SocOverrideSecondsLeft(&s_mon, 1000U));
    TEST_ASSERT_EQUAL_UINT16(300U, BatMon_SocOverrideSecondsLeft(&s_mon, 1001U));
    TEST_ASSERT_EQUAL_UINT16(299U, BatMon_SocOverrideSecondsLeft(&s_mon, 2000U));
    TEST_ASSERT_EQUAL_UINT16(1U, BatMon_SocOverrideSecondsLeft(&s_mon, 300999U));
    TEST_ASSERT_EQUAL_UINT16(0U, BatMon_SocOverrideSecondsLeft(&s_mon, 301000U));

    /* Across the 32-bit tick wrap: set 1.5 s before it, ends 0.5 s after. */
    TEST_ASSERT_EQUAL(BATMON_OK, BatMon_SetSocOverride(&s_mon, 25U, 2U, 0xFFFFFA24U));
    TEST_ASSERT_EQUAL_UINT16(2U, BatMon_SocOverrideSecondsLeft(&s_mon, 0xFFFFFA24U));
    TEST_ASSERT_EQUAL_UINT16(1U, BatMon_SocOverrideSecondsLeft(&s_mon, 0x00000000U));
    TEST_ASSERT_EQUAL_UINT16(0U, BatMon_SocOverrideSecondsLeft(&s_mon, 0x000001F4U));
    ASSERT_BUS_CLEAN();
}

static void test_soc_override_expires_across_tick_wrap(void)
{
    Battery_Snapshot_t snap;

    init_with_soc(80U);

    /* Set 1.5 s before the 32-bit tick wrap for 2 s: it ends at 0x000001F4,
     * 0.5 s after the wrap. */
    TEST_ASSERT_EQUAL(BATMON_OK, BatMon_SetSocOverride(&s_mon, 25U, 2U, 0xFFFFFA24U));
    poll_soc(80U, 0xFFFFFA24U);
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(25U, snap.soc_pct);

    /* Still before the wrap, where the end tick is the SMALLER number: an
     * unsigned "now >= until" would end the override (and poll) here. */
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_Tick(&s_mon, 0xFFFFFC00U));
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_SocOverrideActive(&s_mon));

    /* After the wrap, a regular poll inside the 2 s still uses it. */
    poll_soc(80U, 0x00000100U);
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(25U, snap.soc_pct);

    /* 1 ms before the end: nothing. At the end: over, and an early poll
     * (244 ms after the last one) brings the real 80 % back. */
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_Tick(&s_mon, 0x000001F3U));
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_SocOverrideActive(&s_mon));
    poll_soc(80U, 0x000001F4U);
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_SocOverrideActive(&s_mon));
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(80U, snap.soc_pct);
    ASSERT_BUS_CLEAN();
}

/* The debug screen's Battery OK 60% asks for the longest override, 65535 s
 * (about 18 h), so one push keeps the speaker on for a whole demo even when
 * the gauge itself reads critical. The end time (65 535 000 ms) must not
 * overflow, and the lockout stays released until it is reached. */
static void test_soc_override_max_duration_lasts_about_18_h(void)
{
    Battery_Snapshot_t snap;

    init_with_soc(5U);                                  /* the gauge reads critical */
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsSpeakerLockout(&s_mon));

    TEST_ASSERT_EQUAL(BATMON_OK, BatMon_SetSocOverride(&s_mon, 60U, 65535U, 1000U));
    TEST_ASSERT_EQUAL_UINT16(65535U, BatMon_SocOverrideSecondsLeft(&s_mon, 1000U));
    poll_soc(5U, 1000U);
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsSpeakerLockout(&s_mon));

    /* 1 ms before the end: still 60 %, still released. */
    poll_soc(5U, 1000U + 65534999U);
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(60U, snap.soc_pct);
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsSpeakerLockout(&s_mon));
    TEST_ASSERT_EQUAL_UINT16(1U, BatMon_SocOverrideSecondsLeft(&s_mon, 1000U + 65534999U));

    /* At 65535 s it ends: the real 5 % is back and the lockout sets again. */
    poll_soc(5U, 1000U + 65535000U);
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_SocOverrideActive(&s_mon));
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(5U, snap.soc_pct);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsSpeakerLockout(&s_mon));
    ASSERT_BUS_CLEAN();
}

static void test_soc_override_end_leaves_latches_to_real_soc(void)
{
    init_with_soc(25U);   /* the real battery: 25 %, low alarm on, no lockout */
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsLowBattery(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsSpeakerLockout(&s_mon));

    /* "Battery CRIT 8%", then "Clear overrides": the latches are not reset,
     * they go on from 8 % with the real 25 % and their usual hysteresis.
     * Critical releases (>= 12 %); the lockout holds (< 32 %). */
    TEST_ASSERT_EQUAL(BATMON_OK, BatMon_SetSocOverride(&s_mon, 8U, 300U, 1000U));
    poll_soc(25U, 1000U);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsSpeakerLockout(&s_mon));
    TEST_ASSERT_EQUAL(BATMON_OK, BatMon_SetSocOverride(&s_mon, 0U, 0U, 1100U));
    poll_soc(25U, 1100U);
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsCriticalBattery(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsSpeakerLockout(&s_mon));

    /* "Battery OK 60%" releases it. When that ends, the real 25 % brings the
     * low alarm back but does not lock again: only a drop below 10 % does. */
    TEST_ASSERT_EQUAL(BATMON_OK, BatMon_SetSocOverride(&s_mon, 60U, 1U, 1200U));
    poll_soc(25U, 1200U);
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsSpeakerLockout(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsLowBattery(&s_mon));
    poll_soc(25U, 2200U);
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_SocOverrideActive(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsSpeakerLockout(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsLowBattery(&s_mon));
    ASSERT_BUS_CLEAN();
}

static void test_soc_override_does_not_hide_gauge_failure(void)
{
    Battery_Snapshot_t snap;

    init_with_soc(80U);
    TEST_ASSERT_EQUAL(BATMON_OK, BatMon_SetSocOverride(&s_mon, 8U, 300U, 1000U));

    /* The SOC read itself NACKs: the injected 8 % must not stand in for the
     * missing value. Invalid as always, and the latches do not move, so the
     * speaker is not locked on a broken reading. */
    queue_poll(3300U, -150, 80U, 1700U, 3400U, 0, 0, 1, 0, 0);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_Tick(&s_mon, 1000U));
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(0U, snap.valid);
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsSpeakerLockout(&s_mon));

    /* Voltage outside the window: still rejected by the plausibility check. */
    queue_good_poll(1999U, -150, 80U, 1700U, 3400U);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_Tick(&s_mon, 2000U));
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(0U, snap.valid);
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsSpeakerLockout(&s_mon));

    /* A good reading: now the override takes effect. */
    poll_soc(80U, 3000U);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsSpeakerLockout(&s_mon));
    ASSERT_BUS_CLEAN();
}

static void test_soc_override_is_what_plausibility_check_sees(void)
{
    Battery_Snapshot_t snap;

    init_with_soc(80U);
    TEST_ASSERT_EQUAL(BATMON_OK, BatMon_SetSocOverride(&s_mon, 25U, 300U, 1000U));

    /* Every read succeeds but the gauge's own SOC byte is garbage (200 %).
     * The injected SOC stands in for it in the plausibility check as well,
     * so the poll is valid with 25 % (the voltage is still checked). */
    poll_soc(200U, 1000U);
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(1U, snap.valid);
    TEST_ASSERT_EQUAL_UINT8(25U, snap.soc_pct);
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_IsLowBattery(&s_mon));

    /* Without the override the same reading is rejected as usual. */
    TEST_ASSERT_EQUAL(BATMON_OK, BatMon_SetSocOverride(&s_mon, 0U, 0U, 1100U));
    poll_soc(200U, 1100U);
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(0U, snap.valid);
    ASSERT_BUS_CLEAN();
}

static void test_soc_override_refused_without_gauge(void)
{
    const int absent[] = {-1, -1, -1};
    const int present[] = {0};
    Battery_Snapshot_t snap;

    s_mon.soc_override = 1U;   /* left over from an earlier run: Init must clear it */
    MockBus_QueueReady(absent, 3U);
    TEST_ASSERT_EQUAL(BATMON_NO_GAUGE, BatMon_Init(&s_mon, MockBus_Iface()));
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_SocOverrideActive(&s_mon));

    TEST_ASSERT_EQUAL(BATMON_NO_GAUGE, BatMon_SetSocOverride(&s_mon, 25U, 300U, 1000U));
    TEST_ASSERT_EQUAL(BATMON_NO_GAUGE, BatMon_SetSocOverride(&s_mon, 0U, 0U, 1000U));
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_SocOverrideActive(&s_mon));
    TEST_ASSERT_EQUAL_UINT16(0U, BatMon_SocOverrideSecondsLeft(&s_mon, 1000U));
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_Tick(&s_mon, 1000U));

    /* Nothing was stored: a gauge found later reports its real SOC. */
    MockBus_QueueReady(present, 1U);
    queue_good_poll(3305U, 120, 55U, 1870U, 3400U);
    TEST_ASSERT_EQUAL(BATMON_OK, BatMon_RetryProbe(&s_mon));
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(55U, snap.soc_pct);
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsLowBattery(&s_mon));
    ASSERT_BUS_CLEAN();
}

static void test_soc_override_rejects_soc_above_100(void)
{
    init_with_soc(80U);

    TEST_ASSERT_EQUAL(BATMON_BAD_PARAM, BatMon_SetSocOverride(&s_mon, 101U, 300U, 100U));
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_SocOverrideActive(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_Tick(&s_mon, 100U));   /* nothing stored: no early poll */

    /* A bad value does not replace a running override either. */
    TEST_ASSERT_EQUAL(BATMON_OK, BatMon_SetSocOverride(&s_mon, 25U, 300U, 200U));
    poll_soc(80U, 200U);
    TEST_ASSERT_EQUAL(BATMON_BAD_PARAM, BatMon_SetSocOverride(&s_mon, 200U, 10U, 300U));
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_SocOverrideActive(&s_mon));
    TEST_ASSERT_EQUAL_UINT16(300U, BatMon_SocOverrideSecondsLeft(&s_mon, 200U));
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_Tick(&s_mon, 300U));
    ASSERT_BUS_CLEAN();
}

static void test_soc_override_null_safe(void)
{
    TEST_ASSERT_EQUAL(BATMON_BAD_PARAM, BatMon_SetSocOverride(NULL, 25U, 300U, 0U));
    TEST_ASSERT_EQUAL(BATMON_BAD_PARAM, BatMon_SetSocOverride(NULL, 0U, 0U, 0U));
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_SocOverrideActive(NULL));
    TEST_ASSERT_EQUAL_UINT16(0U, BatMon_SocOverrideSecondsLeft(NULL, 0U));
}

/* -------------------------------------------------------------------------- */
/* Plausibility rejection                                                      */
/* -------------------------------------------------------------------------- */

static void test_soc_above_100_is_rejected(void)
{
    Battery_Snapshot_t snap;

    init_with_soc(80U);

    poll_soc(101U, 1000U);   /* reads succeed but the value is impossible */
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(0U, snap.valid);
    ASSERT_BUS_CLEAN();
}

static void test_voltage_window_boundaries(void)
{
    Battery_Snapshot_t snap;

    init_with_soc(80U);

    /* Below the window: reject. */
    queue_good_poll(1999U, -150, 80U, 1700U, 3400U);
    (void)BatMon_Tick(&s_mon, 1000U);
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(0U, snap.valid);

    /* Window edges are legitimate pack states: accept. */
    queue_good_poll(2000U, -150, 80U, 1700U, 3400U);
    (void)BatMon_Tick(&s_mon, 2000U);
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(1U, snap.valid);

    queue_good_poll(5000U, -150, 80U, 1700U, 3400U);
    (void)BatMon_Tick(&s_mon, 3000U);
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(1U, snap.valid);

    /* Above the window: reject. */
    queue_good_poll(5001U, -150, 80U, 1700U, 3400U);
    (void)BatMon_Tick(&s_mon, 4000U);
    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(0U, snap.valid);
    ASSERT_BUS_CLEAN();
}

/* -------------------------------------------------------------------------- */
/* Retry probe and accessor safety                                             */
/* -------------------------------------------------------------------------- */

static void test_retry_probe_brings_gauge_online(void)
{
    const int absent[] = {-1, -1, -1};
    const int present[] = {0};
    Battery_Snapshot_t snap;

    MockBus_QueueReady(absent, 3U);
    TEST_ASSERT_EQUAL(BATMON_NO_GAUGE, BatMon_Init(&s_mon, MockBus_Iface()));

    /* Gauge board plugged in afterwards (the 5 s re-probe path). */
    MockBus_QueueReady(present, 1U);
    queue_good_poll(3305U, 120, 55U, 1870U, 3400U);
    TEST_ASSERT_EQUAL(BATMON_OK, BatMon_RetryProbe(&s_mon));
    TEST_ASSERT_EQUAL_UINT8(1U, BatMon_GaugePresent(&s_mon));

    BatMon_GetSnapshot(&s_mon, &snap);
    TEST_ASSERT_EQUAL_UINT8(1U, snap.valid);
    TEST_ASSERT_EQUAL_INT16(120, snap.current_mA);
    ASSERT_BUS_CLEAN();
}

static void test_retry_probe_noop_when_present_and_rejects_null(void)
{
    init_with_soc(80U);

    /* Already present: no probing, no reads. */
    TEST_ASSERT_EQUAL(BATMON_OK, BatMon_RetryProbe(&s_mon));
    TEST_ASSERT_EQUAL(BATMON_BAD_PARAM, BatMon_RetryProbe(NULL));
    ASSERT_BUS_CLEAN();
}

static void test_accessors_are_null_safe(void)
{
    Battery_Snapshot_t snap;

    memset(&snap, 0xAA, sizeof(snap));
    BatMon_GetSnapshot(NULL, &snap);
    TEST_ASSERT_EQUAL_UINT8(0U, snap.valid);
    /* An invalid snapshot carries no time estimate and no instant current,
     * not the 0xAAAA left in the caller's buffer. */
    TEST_ASSERT_EQUAL_UINT16(BATMON_TIME_UNKNOWN, snap.tte_min);
    TEST_ASSERT_EQUAL_UINT16(BATMON_TIME_UNKNOWN, snap.ttf_min);
    TEST_ASSERT_EQUAL_INT16(0, snap.current_now_mA);
    TEST_ASSERT_EQUAL_UINT8(0U, snap.current_now_ok);

    BatMon_GetSnapshot(&s_mon, NULL);   /* must simply not crash */

    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsLowBattery(NULL));
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsCriticalBattery(NULL));
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_IsSpeakerLockout(NULL));
    TEST_ASSERT_EQUAL_UINT8(0U, BatMon_GaugePresent(NULL));
}

