    RUN_TEST(test_low_battery_boundary_at_30_percent);
    RUN_TEST(test_critical_battery_boundary_at_10_percent);

    RUN_TEST(test_low_alarm_releases_with_hysteresis_on_rising_soc);
    RUN_TEST(test_critical_alarm_releases_with_hysteresis_on_rising_soc);
    RUN_TEST(test_low_alarm_holds_through_dead_band_chatter);
    RUN_TEST(test_alarm_latch_survives_invalid_poll);
