    RUN_TEST(test_lockout_holds_until_32_percent);
    RUN_TEST(test_lockout_rearms_on_next_drop_below_10_percent);
    RUN_TEST(test_lockout_held_and_reported_through_invalid_polls);
    RUN_TEST(test_lockout_not_set_by_invalid_polls);
    RUN_TEST(test_lockout_latched_by_first_reading_at_init);
    RUN_TEST(test_lockout_cleared_by_init_and_absent_without_gauge);

    RUN_TEST(test_times_unknown_after_init);
    RUN_TEST(test_times_land_in_snapshot);
